# [[соединившись]] с чем-либо, [[образовать]] что-либо новое, целое {{семантика|синонимы=|антонимы=|гиперонимы=|гипонимы=}} {{пример|}}
# {{помета|о коллективе, группе людей}} [[организоваться]], [[создаться]] {{семантика|синонимы=[[организоваться]], [[создаться]]|антонимы=|гиперонимы=|гипонимы=}} {{пример|}}
# [[построиться]], [[возвестись]] путём кладки {{семантика|синонимы=|антонимы=|гиперонимы=[[построиться]], [[возвестись]]|гипонимы=}} {{пример|}}
# [[принять]] определённое положение, вид, форму {{семантика|синонимы=|антонимы=|гиперонимы=сформироваться|гипонимы=}} {{пример|}}
# {{помета|о складных предметах}} [[сближаясь]] отдельными подвижными частями, приобрести компактный вид; также [[предусмотреть]] такую возможность {{семантика|синонимы=|антонимы=|гиперонимы=|гипонимы=}} {{пример|}}
# {{разг.|ru}} [[уложить]], [[упаковать]] свои вещи перед отъездом {{семантика|синонимы=|антонимы=|гиперонимы=[[уложить]], [[упаковать]]|гипонимы=}} {{пример|}}
# {{разг.|ru}} [[устроить]] [[складчина|складчину]] {{семантика|синонимы=|антонимы=|гиперонимы=устроить|гипонимы=}} {{пример|}}
# {{помета|о числах}} [[прибавиться]] [[образовав]] сумму {{семантика|синонимы=прибавиться|антонимы=|гиперонимы=|гипонимы=}} {{пример|}}
# {{помета|о стихах, песнях {{итп}}}} [[сочиниться]] {{семантика|синонимы=сочиниться|антонимы=|гиперонимы=|гипонимы=}} {{пример|}}
# [[обрести]] определённый вид в сознании, воображении {{семантика|синонимы=|антонимы=|гиперонимы=обрести, сформироваться|гипонимы=}} {{пример|}}
# [[возникнуть]] в процессе творчества {{семантика|синонимы=|антонимы=|гиперонимы=возникнуть|гипонимы=}} {{пример|}}
# [[приобрести]] законченную форму, вид, [[структуру]]; [[сформироваться]], [[установиться]] {{семантика|синонимы=|антонимы=|гиперонимы=[[сформироваться]], [[установиться]]|гипонимы=}} {{пример|}}
# [[принять]] тот или иной оборот, течение {{семантика|синонимы=|антонимы=|гиперонимы=принять, стать|гипонимы=}} {{пример|}}
# [[возмужав]], [[приобрести]] определённые физические или душевные качества {{семантика|синонимы=|антонимы=|гиперонимы=приобрести|гипонимы=}} {{пример|}}
# [[определиться]] во всей совокупности характерных свойств, качеств {{семантика|синонимы=|антонимы=|гиперонимы=определиться|гипонимы=}} {{пример|}}
# [[достигнуть]] опытности, мастерства, совершенства в какой-либо области, в овладении какой-либо профессией {{семантика|синонимы=|антонимы=|гиперонимы=достигнуть|гипонимы=}} {{пример|}}
